const profilNode = $('🧠 Lire Profil Supabase').first();
const ideeNode = $('💡 Piocher une Idée').first();
const histoNodes = $('📚 Lire Historique Supabase').all();

const profil = profilNode ? profilNode.json : {};
const idee = ideeNode ? ideeNode.json : {};
const histo = histoNodes || [];

const business = profil.business || "Expert Tech & IA";
const style = profil.style || "Educatif et moderne";
const ton = profil.ton || "Simple et humain";
const mission = profil.mission || "";
const sujets = profil.sujets || "";
const categories = profil.categories || "";
const publicCible = profil.public_cible || "Passionnés de technologie";
const objectifPrincipal = profil.objectif_principal || "";
const motsInterdits = profil.mots_interdits || "";
const styleInterdit = profil.style_interdit || "";
const reglesImportantes = profil.regles_importantes || "";
const typeContenu = profil.type_contenu || "Posts éducatifs";

const sujetDuJour =
idee.sujet_detaille ||
"Parle d'une nouveauté technologique utile";

let derniersPostsArray = [];

for (const item of histo) {
const raw = item.json?.contenu || "";
try {
const parsed = JSON.parse(raw);
derniersPostsArray.push(parsed.content || raw);
} catch (e) {
derniersPostsArray.push(raw);
}
}

const derniersPosts =
derniersPostsArray.slice(0, 5).join(" | ") ||
"Aucun post precedent";

const prompt = `
Tu es un créateur de contenu tech moderne, crédible et intelligent.

IDENTITE :
${business}

MISSION :
${mission}

STYLE :
${style}

TON :
${ton}

SUJETS :
${sujets}

CATEGORIES :
${categories}

PUBLIC CIBLE :
${publicCible}

OBJECTIF :
${objectifPrincipal}

TYPE DE CONTENU :
${typeContenu}

SUJET DU JOUR :
${sujetDuJour}

DERNIERS POSTS A EVITER :
${derniersPosts}

REGLES IMPORTANTES :
${reglesImportantes}

STYLE INTERDIT :
${styleInterdit}

MOTS INTERDITS :
${motsInterdits}

OBJECTIF :

Créer un post Facebook moderne, utile et agréable à lire.

Le post doit :

* sembler humain
* être crédible
* être simple
* être utile immédiatement
* être facile à lire sur mobile
* donner envie de suivre la page
* donner envie de partager

Le post NE DOIT PAS :

* ressembler à du spam
* ressembler à un faux gourou
* utiliser des promesses irréalistes
* utiliser trop d'emojis

STYLE FACEBOOK :

* Paragraphes courts
* Français fluide
* Ton naturel
* Maximum 2 emojis utiles
* Très lisible mobile

LONGUEUR :
Entre 700 et 1400 caractères maximum.

IMPORTANT :
Réponds UNIQUEMENT avec un JSON valide :

{"content":"texte ici"}
`;

const geminiBody = JSON.stringify({
contents: [
{
parts: [
{
text: prompt
}
]
}
],
generationConfig: {
temperature: 0.85,
topP: 0.95,
topK: 40,
maxOutputTokens: 2048
}
});

return [
{
json: {
gemini_body: geminiBody,
idee_id: idee.id || ""
}
}
];

const gemini = $input.first().json;
const prev   =$('✍️ Construire Prompt').first().json;
let raw = '';
try {
  raw = gemini.candidates[0].content.parts[0].text || '';
} catch (e) {
  raw = '';
}
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let content = '';
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    content = parsed.content || '';
  }
} catch (e) {
  content = raw;
}
content = content.replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\').replace(/\n{3,}/g, '\n\n').replace(/[ \t]+/g, ' ').replace(/([a-zA-ZÀ-ÿ])\s*(Et|Tu|Mais|Car|Donc)\s*$/i, '').replace(/["{\[]+$/g, '').trim();
if (content.length > 2200) {
  content = content.substring(0, 2190) + '...';
}
return [{
  json: {
    content: content,
    idee_id: prev.idee_id || ''
  }
}];
